"""Right-click help for every tool: what it does and what it is good for.

``HELP[key] = (what it does, good for, Hungarian: what it does, Hungarian: good for)``.
The key is the tool's icon name, which every ribbon button, list row and palette entry carries.
"""
from PySide6.QtCore import Qt
from PySide6.QtWidgets import QDialog,QVBoxLayout,QHBoxLayout,QLabel,QPushButton,QFrame
from PySide6.QtCore import QSize
from i18n import tr
import i18n
from ui_icons import icon

HELP={
 'select':('Selects and moves sketch geometry. Drag a point or an edge to reshape it; constraints keep holding while you drag.','Adjusting a sketch after drawing it, and picking entities to dimension, constrain or delete.','Vázlatelemeket jelöl ki és mozgat. Egy pont vagy él húzásával átalakíthatod; a kényszerek húzás közben is érvényben maradnak.','Rajzolás utáni finomhangolás, valamint elemek kijelölése méretezéshez, kényszerezéshez vagy törléshez.'),
 'line':('Draws straight lines. Click the start, click each next point; the line chain continues until you press Esc.','Straight edges and polyline outlines, such as the sides of a bracket.','Egyenes vonalakat rajzol. Kattints a kezdőpontra, majd minden következő pontra; a lánc Esc-ig folytatódik.','Egyenes élek és törtvonalas körvonalak, például egy konzol oldalai.'),
 'rectangle':('Draws a rectangle from two opposite corners. Type exact width and height with Tab to switch fields.','Plates, blocks and pockets with square corners.','Téglalapot rajzol két szemközti sarokból. Pontos szélességet és magasságot gépelhetsz, a Tab vált a mezők között.','Derékszögű sarkú lemezek, tömbök és zsebek.'),
 'center_rectangle':('Draws a rectangle from its center point outward.','Rectangles that must stay centered on a point, such as a plate centered on the origin.','Téglalapot rajzol a középpontjától kifelé.','Egy pontra középre igazítandó téglalapok, például az origóra igazított lemez.'),
 'rectangle_3p':('Draws a rectangle at any angle: two points set one edge, the third sets the width.','Rectangles rotated at an angle, such as a slanted plate or a tilted pocket.','Tetszőleges szögű téglalapot rajzol: két pont adja az egyik élt, a harmadik a szélességet.','Elforgatott téglalapok, például egy ferde lemez vagy dőlt zseb.'),
 'circle':('Draws a circle from its center and a radius point or typed radius.','Round holes, shafts and bosses.','Kört rajzol a középpontjából és egy sugárponttal vagy beírt sugárral.','Kerek furatok, tengelyek és csapok.'),
 'circle_3p':('Draws the circle that passes through three points you click.','Recreating a circle when you know three points on it but not its center.','A három kattintott ponton átmenő kört rajzolja meg.','Kör létrehozása, ha három pontját ismered, de a középpontját nem.'),
 'arc':('Draws an arc by start point, end point and a third point that sets the bend.','Curved edges and rounded transitions between two known end points.','Ívet rajzol kezdőpontból, végpontból és a hajlást megadó harmadik pontból.','Ívelt élek és lekerekített átmenetek két ismert végpont között.'),
 'center_arc':('Draws an arc around a center point: click the center, the start point, then move around and click where the arc ends.','Arcs whose center and radius matter, such as flange sectors or round slot ends.','Középpont körüli ívet rajzol: kattints a középpontra, a kezdőpontra, majd mozgasd körbe és kattints a végére.','Olyan ívek, ahol a középpont és a sugár számít, például peremszeletek vagy kerek hornyvégek.'),
 'ellipse':('Draws an ellipse: center, the end of the major axis, then the minor radius.','Oval holes and shafts, and slanted round cross sections.','Ellipszist rajzol: középpont, a nagytengely végpontja, majd a kissugár.','Ovális furatok és tengelyek, ferdén metszett kerek keresztmetszetek.'),
 'polygon':('Draws a regular polygon with the number of sides set in the side panel.','Hex nut and bolt-head outlines, or any equal-sided shape such as a triangle or an octagon.','Szabályos sokszöget rajzol; az oldalak száma az oldalsó panelen állítható.','Hatszögű anya- és csavarfej-körvonalak, vagy bármilyen egyenlő oldalú alakzat, például háromszög vagy nyolcszög.'),
 'slot':('Draws a slot from two center points and a width.','Mounting slots that allow adjustment, and keyways.','Hornyot rajzol két középpontból és egy szélességből.','Állítást lehetővé tevő rögzítő hornyok és ékhornyok.'),
 'spline':('Draws a smooth free-form curve through control points. Click the first point again to close it.','Smooth curved outlines, such as handles and ergonomic shapes, that are not made of lines and arcs.','Sima, szabad formájú görbét rajzol vezérlőpontokon át. Az első pontra kattintva zárhatod.','Sima ívelt körvonalak, például fogantyúk és ergonomikus formák, amelyek nem egyenesekből és ívekből állnak.'),
 'conic':('Draws a conic curve from two end points and a control point.','Arcs with a custom curvature, such as a parabolic reflector or a smooth blend between two lines.','Kúpgörbét rajzol két végpontból és egy vezérlőpontból.','Egyedi görbületű ívek, például parabolatükör vagy sima átmenet két vonal között.'),
 'point':('Places a reference point in the sketch.','Marking a position, such as a hole center, that other geometry can snap to.','Referenciapontot helyez el a vázlatban.','Egy pozíció, például furatközéppont megjelölése, amelyhez más geometria illeszkedhet.'),
 'text':('Places text: drag a box, then set font, size, alignment and the words in the side panel. The letters become sketch outlines.','Labels, part numbers and logos that are engraved or embossed.','Szöveget helyez el: húzz egy dobozt, majd az oldalsó panelen állítsd be a betűtípust, méretet, igazítást és a szöveget. A betűk vázlatkörvonalakká válnak.','Vésett vagy domború feliratok, alkatrészszámok és logók.'),
 'trim':('Cuts a sketch curve back to the nearest crossing. Click the piece you want to remove.','Cleaning up lines that cross or overlap, so the profile closes into one region.','Egy vázlatgörbét a legközelebbi metszésig levág. Kattints az eltávolítandó darabra.','Keresztező vagy átfedő vonalak tisztítása, hogy a profil egy területté záruljon.'),
 'extend':('Lengthens a line or arc from the end you click to the next curve it meets.','Closing a gap between a line and a wall, or running a line out to meet another one.','Meghosszabbít egy vonalat vagy ívet a kattintott végétől a következő görbéig, amellyel találkozik.','Egy vonal és egy fal közötti rés megszüntetése, vagy vonal kifuttatása egy másikig.'),
 'offset':('Creates curves at a set distance from the ones you select. A closed outline grows for a positive distance; the originals stay.','Walls of a constant thickness, clearance outlines and parallel guide lines.','Meghatározott távolságra lévő görbéket hoz létre a kijelöltektől. Zárt körvonal pozitív távolságnál nő; az eredetiek megmaradnak.','Állandó falvastagság, hézag-körvonalak és párhuzamos segédvonalak.'),
 'transform':('Moves, rotates or scales the selected sketch geometry by exact values. Copy keeps the original.','Repositioning part of a sketch, or making a rotated or scaled copy of it.','A kijelölt vázlatelemeket pontos értékekkel mozgatja, forgatja vagy skálázza. A másolás megtartja az eredetit.','A vázlat egy részének áthelyezése, vagy elforgatott, skálázott másolat készítése.'),
 'sketch_fillet':('Rounds a corner where two sketch curves meet. Pick the corner, then drag the arrow or type the radius.','Rounding sharp corners of a profile before extruding it.','Lekerekít egy sarkot, ahol két vázlatgörbe találkozik. Válaszd ki a sarkot, majd húzd a nyilat vagy írd be a sugarat.','Egy profil éles sarkainak lekerekítése kihúzás előtt.'),
 'sketch_chamfer':('Cuts a straight bevel across a corner of two sketch curves.','Beveling the corners of a profile, such as the corners of a plate.','Egyenes letörést vág két vázlatgörbe sarkán.','Egy profil sarkainak letörése, például egy lemez sarkain.'),
 'mirror':('Mirrors selected sketch geometry across a line.','Symmetric profiles: draw one half and mirror it to get the other.','A kijelölt vázlatelemeket egy vonalra tükrözi.','Szimmetrikus profilok: rajzold meg az egyik felet, és tükrözéssel kapod a másikat.'),
 'circular':('Repeats selected sketch geometry around a center point.','Holes or teeth spaced evenly around a center, such as a bolt circle.','A kijelölt vázlatelemeket egy középpont körül megismétli.','Egy középpont körül egyenletesen elosztott furatok vagy fogak, például csavarkör.'),
 'rectangular':('Repeats selected sketch geometry in rows and columns.','Grids of repeated holes or slots, such as vents or perforated plates.','A kijelölt vázlatelemeket sorokban és oszlopokban megismétli.','Ismétlődő furatok vagy rések rácsa, például szellőzők vagy perforált lemezek.'),
 'project':("Copies model edges or another sketch's lines into this sketch, linked to the source. Project flattens them onto the sketch plane; Include keeps them as they are.",'Drawing a new profile that lines up with an edge of an existing body or another sketch.','Modell éleket vagy másik vázlat vonalait másolja ebbe a vázlatba, a forráshoz kapcsolva. A Vetítés a vázlatsíkra lapítja, a Befoglalás változatlanul tartja.','Olyan új profil rajzolása, amely illeszkedik egy meglévő test vagy másik vázlat éléhez.'),
 'construction':('Switches the drawing to guide mode: new lines are helpers that never become part of a profile.','Center lines, symmetry axes and layout lines that help drawing but must not become part of the part.','Segédvonal módba kapcsol: az új vonalak segédek, sosem lesznek a profil részei.','Középvonalak, szimmetriatengelyek és szerkesztővonalak, amelyek segítik a rajzolást, de nem lesznek az alkatrész részei.'),
 'sketch_move':('Moves a whole sketch to a new position.','Repositioning a finished sketch without redrawing it.','Egy teljes vázlatot új helyre mozgat.','Kész vázlat áthelyezése újrarajzolás nélkül.'),
 'finish':('Finishes the sketch and returns to the 3D model.','Closing the sketch once the profile is complete, so you can extrude or revolve it.','Befejezi a vázlatot, és visszatér a 3D modellhez.','A vázlat lezárása, ha a profil kész, hogy kihúzhasd vagy elforgathasd.'),
 'cancel':('Discards the sketch you are working on.','Dropping a sketch you started by mistake or no longer need.','Elveti a készülő vázlatot.','Tévesen elkezdett vagy már nem szükséges vázlat eldobása.'),
 'constraint':('Opens the constraint tools that lock sketch geometry: horizontal, tangent, equal and so on.','Making a sketch keep its shape when you change a dimension.','Megnyitja a kényszereszközöket, amelyek rögzítik a vázlatgeometriát: vízszintes, érintő, egyenlő stb.','Hogy a vázlat megtartsa az alakját, amikor egy méretet módosítasz.'),
 'coincident':('Forces two points to share the same position.','Joining the ends of lines so a profile closes without gaps.','Két pontot ugyanabba a helyzetbe kényszerít.','Vonalvégek összekötése, hogy a profil hézag nélkül záruljon.'),
 'horizontal':('Keeps a line parallel to the sketch X axis.','Edges that must stay level, such as a table top.','Egy vonalat a vázlat X tengelyével párhuzamosan tart.','Vízszintesen maradó élek, például egy asztallap.'),
 'vertical':('Keeps a line parallel to the sketch Y axis.','Edges that must stay upright, such as a wall or a post.','Egy vonalat a vázlat Y tengelyével párhuzamosan tart.','Függőleges maradó élek, például egy fal vagy oszlop.'),
 'parallel':('Keeps two lines parallel to each other.','Opposite sides of a slot, a rail or a strip.','Két vonalat egymással párhuzamosan tart.','Egy horony, sín vagy szalag szemközti oldalai.'),
 'perpendicular':('Keeps two lines at a right angle.','Square corners that are not aligned with the grid.','Két vonalat derékszögben tart.','A rácshoz nem igazodó derékszögű sarkok.'),
 'tangent':('Makes a line and a curve (or two curves) meet smoothly, with no corner.','Blending a line smoothly into an arc, so there is no visible corner.','Egy vonal és egy görbe (vagy két görbe) sima, törés nélküli csatlakozását hozza létre.','Egy vonal sima ívbe olvasztása, hogy ne legyen látható törés.'),
 'equal':('Gives two lines the same length, or two circles the same radius.','Making several holes the same size, or the sides of a square the same length.','Két vonalnak azonos hosszt, két körnek azonos sugarat ad.','Több furat azonos méretűre állítása, vagy egy négyzet oldalainak azonos hosszra állítása.'),
 'concentric':('Puts two circles or arcs on the same center.','Rings, washers and counterbored holes that share one center.','Két kört vagy ívet azonos középpontra helyez.','Közös középpontú gyűrűk, alátétek és süllyesztett furatok.'),
 'collinear':('Puts two lines on the same straight line.','Edges that must continue each other along one straight line.','Két vonalat ugyanarra az egyenesre helyez.','Olyan élek, amelyeknek egy egyenes mentén folytatniuk kell egymást.'),
 'midpoint':('Forces a point to sit at the middle of a line.','Centering a point, such as a hole, on the middle of an edge.','Egy pontot egy vonal felezőpontjára kényszerít.','Egy pont, például egy furat, egy él közepére igazítása.'),
 'point_on_object':('Forces a point to stay on a line, arc or circle.','Keeping a point on a line or curve, so it slides along it but never leaves it.','Egy pontot arra kényszerít, hogy vonalon, íven vagy körön maradjon.','Egy pont vonalon vagy görbén tartása: végigcsúszhat rajta, de nem hagyhatja el.'),
 'symmetry':('Makes two points mirror images of each other about a line.','Keeping a design symmetric even after you edit one side.','Két pontot egy vonalra nézve egymás tükörképévé tesz.','A terv szimmetrikusan tartása akkor is, ha az egyik oldalt szerkeszted.'),
 'fix':('Locks a point or curve in place so it cannot move.','Locking the part of a sketch that must not move while you adjust the rest.','Egy pontot vagy görbét a helyén rögzít, hogy ne mozdulhasson.','A vázlat azon részének rögzítése, amelynek nem szabad elmozdulnia, miközben a többit állítod.'),
 'unfix':('Releases a fixed point or curve again.','Making a locked part of a sketch editable again.','Egy rögzített pontot vagy görbét ismét felszabadít.','A vázlat egy rögzített részének újra szerkeszthetővé tétele.'),
 'dimension':('Adds a driving dimension: type a value and the geometry resizes to match.','Setting exact sizes that you can change later to resize the whole part.','Vezérlő méretet ad hozzá: írj be egy értéket, és a geometria ehhez igazodik.','Pontos méretek megadása, amelyeket később módosítva az egész alkatrész átméretezhető.'),
 'sketch':('Starts a new sketch on an origin plane, a construction plane or a flat face of a body.','Starting every new part or feature: the profile you draw becomes a solid.','Új vázlatot indít egy origósíkon, segédsíkon vagy egy test sík lapján.','Minden új alkatrész vagy elem kezdete: a megrajzolt profilból lesz a test.'),
 'extrude':('Pushes closed sketch profiles or flat faces into a solid. Drag the arrow or type the depth; choose add, cut or intersect.','Turning a drawn profile into a plate or block, cutting pockets and pushing bosses out of a face.','Zárt vázlatprofilokat vagy sík lapokat szilárd testté húz ki. Húzd a nyilat vagy írd be a mélységet; hozzáadás, kivágás vagy metszet választható.','Megrajzolt profil lemezzé vagy tömbbé alakítása, zsebek kivágása és csapok kihúzása egy lapból.'),
 'fillet':('Rounds the selected edges of a solid. Click edges, then drag the arrow or type the radius.','Removing sharp edges to make a part stronger, safer to handle or softer looking.','A test kijelölt éleit lekerekíti. Kattints élekre, majd húzd a nyilat vagy írd be a sugarat.','Éles élek eltüntetése, hogy az alkatrész erősebb, biztonságosabb vagy lágyabb megjelenésű legyen.'),
 'chamfer':('Cuts a flat bevel along the selected edges of a solid.','Easing edges so parts fit together, or adding a bevel at the mouth of a hole.','Sík letörést vág a test kijelölt élei mentén.','Élek tompítása, hogy az alkatrészek illeszkedjenek, vagy letörés egy furat szájánál.'),
 'solid_tools':('Opens the list of solid creation tools: revolve, sweep, loft, hole, pipe, coil, thread and more.','Making shapes that a plain extrusion cannot, such as round, swept or lofted bodies.','Megnyitja a szilárdtest-készítő eszközök listáját: forgatás, söprés, átmenet, furat, cső, csavarvonal, menet és más.','Olyan alakzatok készítése, amelyeket egy egyszerű kihúzás nem tud, például forgás-, söpréses vagy átmenetes testek.'),
 'solid_modify':('Opens more modify tools: shell, draft, offset face, press pull, scale, replace and split face.','Reworking a body that already exists: hollowing it out, tilting faces or moving faces.','Megnyitja a további módosító eszközöket: héj, dőlés, lap eltolás, nyomás-húzás, méretezés, lapcsere és lapfelosztás.','Egy már meglévő test átdolgozása: kiüregesítés, lapok megdöntése vagy mozgatása.'),
 'body_tools':('Opens body-level tools: combine, split, move or copy whole bodies.','Working with whole bodies: joining parts, cutting a body in two or positioning it.','Megnyitja a testszintű eszközöket: egyesítés, felosztás, egész testek mozgatása vagy másolása.','Egész testekkel dolgozás: alkatrészek egyesítése, test kettévágása vagy pozicionálása.'),
 'body_patterns':('Opens pattern tools that repeat features, faces or whole bodies.','Repeating features, faces or bodies, such as rows of holes or mirrored parts.','Megnyitja a mintázat-eszközöket, amelyek elemeket, lapokat vagy egész testeket ismétlenek meg.','Elemek, lapok vagy testek ismétlése, például furatsorok vagy tükrözött alkatrészek.'),
 'construct':('Opens construction tools: offset, angled, mid and three-point planes, axes and surface sketches.','Creating a plane or axis where the model has none to sketch on or revolve around.','Megnyitja a segédgeometria-eszközöket: eltolt, szögben álló, középsík, háromponttal megadott sík, tengely és felületi vázlat.','Sík vagy tengely létrehozása ott, ahol a modellen nincs vázlatolható felület vagy forgástengely.'),
 'measure':('Measures distances, radii, angles and areas between points, edges and faces you click.','Checking that a part has the size you intended before you export or make it.','Távolságot, sugarat, szöget és területet mér a rákattintott pontok, élek és lapok között.','Annak ellenőrzése, hogy az alkatrész a tervezett méretű-e, mielőtt exportálod vagy legyártod.'),
 'repair':('Finds broken references in the history and lets you re-point them to valid geometry.','Recovering an older project where a change made a later step fail.','Megkeresi az előzmények törött hivatkozásait, és érvényes geometriára irányíthatod át.','Régebbi projekt helyreállítása, ahol egy módosítás miatt egy későbbi lépés meghibásodott.'),
 'revolve':('Spins a sketch profile around an axis to make a round solid.','Round parts whose profile repeats all the way around, such as wheels, bottles and pulleys.','Egy vázlatprofilt egy tengely körül forgat, hogy forgástestet hozzon létre.','Kerek alkatrészek, amelyek profilja körben ismétlődik, például kerekek, palackok és szíjtárcsák.'),
 'sweep':('Drags a profile along a path curve. Click the profile, then click the path in the workspace.','Parts with a constant cross-section that follows a curve, such as handles, rails and cables.','Egy profilt húz végig egy pályagörbe mentén. Kattints a profilra, majd a pályára a munkaterületen.','Állandó keresztmetszetű, görbét követő alkatrészek, például fogantyúk, sínek és kábelek.'),
 'loft':('Blends smoothly between two or more profiles. Click the sections in order.','Smooth transitions between different shapes, such as a round to a square opening.','Sima átmenetet készít két vagy több profil között. Kattints sorban a szelvényekre.','Sima átmenet különböző formák között, például kerekből négyzet alakú nyílásba.'),
 'hole':('Drills a simple, counterbored or countersunk hole at a position on a face.','Screw holes, dowel holes and through holes, placed at an exact position.','Egyszerű, süllyesztett vagy kúpos furatot fúr egy lap adott pontján.','Csavarfuratok, szegfuratok és átmenő furatok pontos pozícióban.'),
 'primitive':('Creates a box, cylinder, sphere, cone or torus by size alone, with no sketch.','Quick base blocks, placeholders and simple bodies you cut into afterwards.','Vázlat nélkül, csak méretek megadásával hoz létre dobozt, hengert, gömböt, kúpot vagy tóruszt.','Gyors alaptömbök, helykitöltők és egyszerű testek, amelyekbe utána vágsz.'),
 'pipe':('Makes a round tube (solid or hollow) along a path curve. Click the path in the workspace.','Tubes and rods that follow a path, such as pipework, handrails or wire frames.','Kerek csövet (tömör vagy üreges) készít egy pálya mentén. Kattints a pályára a munkaterületen.','Pályát követő csövek és rudak, például csővezetékek, korlátok vagy drótvázak.'),
 'coil':('Winds a round wire into a helix around an axis. Click a cylinder to take its axis and radius.','Springs and coiled wire.','Kerek drótot csavarvonalba tekercsel egy tengely körül. Kattints egy hengerre a tengelyének és sugarának átvételéhez.','Rugók és tekercselt drót.'),
 'thread':('Cuts a helical groove on a shaft or inside a hole. Click the cylinder to take its size.','Bolts, screws, nuts and threaded holes.','Csavarvonalú hornyot vág egy tengelyre vagy furat belsejébe. Kattints a hengerre a méretének átvételéhez.','Csavarok, menetes szárak, anyák és menetes furatok.'),
 'rib':('Adds a thin supporting wall standing on a sketch line, growing out of the sketch plane.','Stiffening a thin plate or bracket without making the whole part thicker.','Vékony merevítő falat ad hozzá, amely egy vázlatvonalon áll és a vázlatsíkból nő ki.','Vékony lemez vagy konzol merevítése anélkül, hogy az egész alkatrészt vastagítanád.'),
 'web':('Adds a thin wall centered on the sketch plane, half above and half below.','Cross-bracing inside a hollow part, or a thin wall that should sit centered on a plane.','Vékony falat ad hozzá, amely a vázlatsíkra középre igazított, fele fent, fele lent.','Üreges alkatrész belső keresztmerevítése, vagy egy síkra középre igazítandó vékony fal.'),
 'component':('Opens the assembly tools: components, joints and links between parts.','Building a product from several parts that fit together or move relative to each other.','Megnyitja az összeállítás-eszközöket: komponensek, kötések és kapcsolatok az alkatrészek között.','Több, egymáshoz illeszkedő vagy egymáshoz képest mozgó alkatrészből álló termék építése.'),
 'joint':('Connects two components with a rigid or moving joint.','Hinges, sliders and rotating connections between two parts.','Két komponenst merev vagy mozgó kötéssel kapcsol össze.','Zsanérok, csúszkák és forgó kapcsolatok két alkatrész között.'),
 'surface_patch':('Opens surface tools: surfaces are zero-thickness skins you can later stitch or thicken.','Smooth freeform shapes, like a car body panel, that are hard to build from solids.','Megnyitja a felületeszközöket: a felületek vastagság nélküli héjak, amelyeket később összevarrhatsz vagy vastagíthatsz.','Sima, szabad formájú alakzatok, például karosszériaelemek, amelyeket nehéz tömör testekből építeni.'),
 'surface_extrude':('Pushes a curve or profile out into a surface.','Open walls and skins, such as a panel that will be thickened later.','Egy görbét vagy profilt felületté húz ki.','Nyitott falak és héjak, például egy később vastagítandó panel.'),
 'surface_revolve':('Spins a curve around an axis into a surface.','Open round shapes, such as a bowl, funnel or dome, before they get a thickness.','Egy görbét tengely körül forgatva felületet készít.','Nyitott kerek formák, például tál, tölcsér vagy kupola, mielőtt vastagságot kapnak.'),
 'surface_sweep':('Drags a curve along a path into a surface.','Curved panels and ducts that follow a path and stay open.','Egy görbét egy pálya mentén húzva felületet készít.','Pályát követő, nyitott ívelt panelek és csatornák.'),
 'surface_loft':('Blends a surface through several curves.','Smooth skins between several outlines, such as a hull or a streamlined cover.','Felületet simít át több görbén.','Sima héjak több körvonal között, például hajótest vagy áramvonalas burkolat.'),
 'surface_stitch':('Joins touching surfaces into one, and into a solid if they close up.','Joining separate surfaces into one, and into a solid when they enclose a volume.','Az érintkező felületeket eggyé varrja, és ha lezárnak, szilárd testté.','Különálló felületek eggyé, és ha térfogatot zárnak közre, szilárd testté varrása.'),
 'surface_trim':('Cuts a surface back with another surface or curve.','Cutting a surface back to a boundary, for example after you extended it too far.','Egy felületet egy másik felülettel vagy görbével levág.','Egy felület levágása egy határig, például ha túl messzire nyújtottad.'),
 'surface_extend':('Makes a surface larger beyond its edge.','Making a surface reach a boundary before you trim or stitch it.','Egy felületet a szélén túl megnagyobbít.','Egy felület kinyújtása egy határig, mielőtt levágod vagy összevarrod.'),
 'surface_thicken':('Gives a surface a wall thickness, turning it into a solid.','Turning a surface into a solid sheet or shell with a wall thickness.','Falvastagságot ad egy felületnek, és szilárd testté alakítja.','Egy felület falvastagsággal rendelkező szilárd lemezzé vagy héjjá alakítása.'),
 'shell':('Hollows a solid out, leaving walls of a set thickness. Click faces to open.','Making boxes, enclosures and bottles: parts that are empty inside with thin walls.','Kiüregesít egy testet, adott falvastagságot hagyva. Kattints a nyitandó lapokra.','Dobozok, burkolatok és palackok készítése: belül üres, vékony falú alkatrészek.'),
 'draft':('Tilts selected faces by an angle around a neutral plane.','Molded or cast parts, so they can be released from the mold.','A kijelölt lapokat egy semleges sík körül adott szöggel megdönti.','Öntött vagy fröccsöntött alkatrészek, hogy kivehetők legyenek a formából.'),
 'offset_face':('Moves selected faces in or out by a distance.','Making a boss taller, a wall thicker or a pocket deeper without redrawing a sketch.','A kijelölt lapokat adott távolsággal be- vagy kifelé mozgatja.','Csap magasabbá, fal vastagabbá vagy zseb mélyebbé tétele vázlat újrarajzolása nélkül.'),
 'press_pull':('Pushes or pulls faces or sketch profiles directly. Drag the arrow or type a distance.','Quick direct edits: pushing a face in or pulling it out to remove or add material.','Lapokat vagy vázlatprofilokat közvetlenül nyom vagy húz. Húzd a nyilat vagy írj be egy távolságot.','Gyors közvetlen szerkesztés: egy lap benyomása vagy kihúzása anyag eltávolításához vagy hozzáadásához.'),
 'scale':('Scales a body larger or smaller around a pivot point.','Resizing an imported part, or fitting a part to a different size.','Egy testet egy forgáspont körül nagyít vagy kicsinyít.','Importált alkatrész átméretezése, vagy egy alkatrész másik méretre igazítása.'),
 'replace_face':('Replaces a face with a different plane, reshaping the body to meet it.','Squaring off a slanted end, or making a face match a reference plane.','Egy lapot egy másik síkkal helyettesít, a testet ehhez igazítva.','Ferde vég derékszögűvé tétele, vagy egy lap egy referenciasíkhoz igazítása.'),
 'split_face':('Cuts a face into pieces along a curve, without changing the shape.','Marking out an area on a face that you then press, offset or draft on its own.','Egy lapot egy görbe mentén részekre vág, az alakot nem változtatva.','Egy lapon belüli terület kijelölése, amelyet aztán külön nyomhatsz, tolhatsz vagy dönthetsz.'),
 'body_combine':('Joins, cuts or intersects bodies with each other.','Merging parts into one body, or cutting a shape out of a body with another body.','Testeket egyesít, kivág vagy metsz egymással.','Alkatrészek egy testté olvasztása, vagy egy forma kivágása egy testből egy másik testtel.'),
 'body_split':('Cuts a body into several using a plane or a surface.','Dividing a part into pieces, for example to print or machine it in sections.','Egy testet több darabra vág egy síkkal vagy felülettel.','Alkatrész darabokra osztása, például szakaszos nyomtatáshoz vagy megmunkáláshoz.'),
 'body_move':('Moves, rotates or copies whole bodies.','Positioning parts relative to each other, or making a moved copy.','Egész testeket mozgat, forgat vagy másol.','Alkatrészek egymáshoz képesti elhelyezése, vagy mozgatott másolat készítése.'),
 'body_mirror':('Makes a mirrored copy of whole bodies across a plane.','Left and right versions of a part, or a symmetric copy of a whole body.','Egész testekről tükrözött másolatot készít egy síkra.','Egy alkatrész bal és jobb változata, vagy egy egész test szimmetrikus másolata.'),
 'body_rectangular':('Repeats whole bodies in rows and columns.','Placing many copies of a part in a grid, such as feet, clips or spacers.','Egész testeket sorokban és oszlopokban ismétel.','Egy alkatrész sok másolatának rácsban elhelyezése, például lábak, kapcsok vagy távtartók.'),
 'body_circular':('Repeats whole bodies around an axis.','Parts spaced evenly around an axis, such as bolts around a flange or blades around a hub.','Egész testeket egy tengely körül ismétel.','Egy tengely körül egyenletesen elosztott alkatrészek, például csavarok egy perem körül vagy lapátok egy agy körül.'),
 'feature_rectangular':('Repeats a feature (such as a hole or boss) in rows and columns on the same body.','Grids of holes, ribs or perforations on one body.','Egy elemet (pl. furatot vagy csapot) sorokban és oszlopokban ismétel ugyanazon a testen.','Furatok, bordák vagy perforációk rácsa egyetlen testen.'),
 'feature_circular':('Repeats a feature around an axis.','Bolt circles, spokes and radial cuts on one body.','Egy elemet egy tengely körül ismétel.','Csavarkörök, küllők és sugaras vágások egyetlen testen.'),
 'feature_mirror':('Mirrors a feature across a plane on the same body.','Details that must stay symmetric, such as holes on both sides of a part.','Egy elemet egy síkra tükröz ugyanazon a testen.','Szimmetrikusnak maradó részletek, például furatok egy alkatrész mindkét oldalán.'),
 'path_pattern':('Repeats a feature along a path curve. Click the path in the workspace.','Placing repeated features along a curve, such as rivets along an edge.','Egy elemet egy pálya mentén ismétel. Kattints a pályára a munkaterületen.','Ismétlődő elemek elhelyezése egy görbe mentén, például szegecsek egy él mentén.'),
 'offset_plane':('Creates a plane parallel to a face or plane, at a distance. Drag the arrow to set it.','Sketching at a level where the part has no face, such as halfway up its height.','Egy lappal vagy síkkal párhuzamos síkot hoz létre adott távolságra. A nyíl húzásával állítható.','Vázlatkészítés olyan szinten, ahol az alkatrésznek nincs lapja, például a magasság felénél.'),
 'angled_plane':('Creates a plane tilted around an axis by an angle.','Slanted cuts and sloped surfaces that are not at 90 degrees to anything.','Egy tengely körül adott szöggel megdöntött síkot hoz létre.','Ferde vágások és lejtős felületek, amelyek semmihez sem derékszögűek.'),
 'section':('Cuts the view of the model with a movable plane so you can look inside. Drag the arrow or type the position; the cut face is shown hatched. The model itself does not change.','Checking wall thickness, hidden holes and how parts fit together inside an assembly.','Egy mozgatható síkkal elvágja a modell nézetét, így beleláthatsz. Húzd a nyilat vagy írd be a helyzetet; a vágott felület vonalkázva látszik. Maga a modell nem változik.','Falvastagság, rejtett furatok és a belső illeszkedések ellenőrzése egy összeállításban.'),
 'midplane':('Creates a plane exactly halfway between two planes or faces.','Centering a feature between two walls, or a plane of symmetry.','Pontosan két sík vagy lap közötti felező síkot hoz létre.','Egy elem két fal közé középre igazítása, vagy szimmetriasík.'),
 'three_point_plane':('Creates a plane through three points you click.','Sketching on a plane defined by three corners, such as a slanted cut across a part.','Három rákattintott ponton átmenő síkot hoz létre.','Három sarokpont által meghatározott síkon való vázlatkészítés, például egy ferde átvágás egy alkatrészen.'),
 'construction_axis':('Creates an axis line through two points.','Rotation axes for revolve, circular patterns and threads when no edge is in the right place.','Két ponton átmenő tengelyvonalat hoz létre.','Forgástengelyek forgatáshoz, körmintákhoz és menetekhez, ha egyetlen él sincs a megfelelő helyen.'),
 'sketch3d':('Draws lines and curves in 3D space instead of on a flat plane.','Path curves that bend in all three directions, such as a cable route.','Vonalakat és görbéket rajzol a 3D térben, nem sík lapon.','Mindhárom irányban hajló pályagörbék, például kábelvezetés.'),
 'surface_sketch':('Draws a sketch that lies on a curved surface.','Marking curves or split lines directly on a curved face.','Görbült felületen fekvő vázlatot rajzol.','Görbék vagy vágóvonalak jelölése közvetlenül egy ívelt lapon.'),
}


def help_for(key):
    return HELP.get(str(key))


def publish_translations():
    """Hungarian texts into the main translation table."""
    for what,good,hu_what,hu_good in HELP.values():
        i18n.HU[what]=hu_what;i18n.HU[good]=hu_good
    i18n.HU.update({'What it does':'Mit csinál','Good for':'Mire jó','Close':'Bezárás','Right-click any tool to see this description.':'Jobb kattintás bármelyik eszközre: megjelenik ez a leírás.'})


publish_translations()


class ToolHelpDialog(QDialog):
    """A small window centered over the main window: the tool's name, what it does, what it is good for."""
    def __init__(self,window,key,title):
        super().__init__(window);self.setWindowTitle(title);self.setModal(False);self.setAttribute(Qt.WA_DeleteOnClose)
        what,good,_,_=HELP[key]
        layout=QVBoxLayout(self);layout.setContentsMargins(20,18,20,16);layout.setSpacing(10)
        head=QHBoxLayout();head.setSpacing(12)
        picture=QLabel();picture.setPixmap(icon(key if key not in ('sketch_fillet','sketch_chamfer') else key).pixmap(40,40));head.addWidget(picture)
        name=QLabel(title);name.setStyleSheet('font-size: 18px; font-weight: 700;');head.addWidget(name,1);layout.addLayout(head)
        divider=QFrame();divider.setFrameShape(QFrame.HLine);divider.setObjectName('ribbonDivider');layout.addWidget(divider)
        for heading,text in (('What it does',what),('Good for',good)):
            label=QLabel(tr(heading));label.setStyleSheet('font-weight: 700;');layout.addWidget(label)
            body=QLabel(tr(text));body.setWordWrap(True);body.setMinimumWidth(340);layout.addWidget(body)
        close=QPushButton(tr('Close'));close.clicked.connect(self.close);layout.addWidget(close,0,Qt.AlignRight)
        self.setFixedWidth(420);self.adjustSize()
        center=window.geometry().center();self.move(center.x()-self.width()//2,center.y()-self.height()//2)


def show_tool_help(window,key,title):
    if help_for(key) is None:return False
    old=getattr(window,'tool_help_dialog',None)
    if old is not None:
        try:old.close()
        except RuntimeError:pass
    dialog=ToolHelpDialog(window,key,title);window.tool_help_dialog=dialog
    dialog.show();dialog.raise_();return True
